        description="Every Nxeon game server ships with full SFTP, an in-dashboard file manager, and live console access, so you can install anything your game's modding platform supports. Minecraft, Rust, and Valheim also include a genuine one-click Mod Store."
        url={`${APP_URL}/game-servers`}
        offers={MOD_OFFERS}
      />
      <FaqJsonLd items={MODS_CONTENT.faq} />
      <ModsTemplate content={MODS_CONTENT} reviewBadges={<ReviewBadges />} />
    </>
  );
}

